code_examples.vulnerable:
// 변수의 초기값을 지정하지 않을 경우 공격에 사용 될 수 있어 안전하지 않다.
int x, y;
switch(position) {
    case 0: x = base_position; y = base_position beak;
    case 1: x = base_position + i; y = base_position - i break;
    default: x=1; break;
}
setCursorPosition(x,y);

code_examples.safe:
// 변수의 초기값은 항상 지정하여야 한다.
int x=1, y=1;
switch(position) {
    case 0: x = base_position; y = base_position beak;
    case 1: x = base_position + i; y = base_position - i break;
    default: x=1; break;
}
setCursorPosition(x,y);
